def _normalize(text: str) -> str:
    return " ".join(text.split())


TRANSLATIONS_HE = {_normalize(en): he for en, he in _T.items()}


def to_hebrew(text: str | None) -> str | None:
    """Hebrew translation of a rubric or expected behavior, or None if there is none."""
    if not text:
        return None
    return TRANSLATIONS_HE.get(_normalize(text))
